ALTER TABLE "execution_commands" ADD CONSTRAINT "execution_commands_owner_shape_check" CHECK (("execution_commands"."owner_kind" IS NULL AND "execution_commands"."owner_ref" IS NULL AND "execution_commands"."logical_operation_key" IS NULL AND "execution_commands"."request_schema" IS NULL AND "execution_commands"."request_sha256" IS NULL) OR ("execution_commands"."owner_kind" IN ('flow_node_attempt', 'scratch_message', 'gate_chat', 'agent_turn', 'sync_resolution') AND jsonb_typeof("execution_commands"."owner_ref") = 'object' AND "execution_commands"."logical_operation_key" IS NOT NULL AND "execution_commands"."request_schema" IS NOT NULL AND "execution_commands"."request_sha256" ~ '^[a-f0-9]{64}$'));--> statement-breakpoint
ALTER TABLE "execution_events" ADD CONSTRAINT "execution_events_source_shape_check" CHECK (("execution_events"."source" = 'host' AND "execution_events"."event_stream_id" IS NOT NULL AND "execution_events"."host_sequence" IS NOT NULL) OR ("execution_events"."source" IN ('manager', 'legacy_import') AND "execution_events"."source_key" IS NOT NULL AND "execution_events"."event_stream_id" IS NULL AND "execution_events"."host_sequence" IS NULL));--> statement-breakpoint
ALTER TABLE "execution_events" ADD CONSTRAINT "execution_events_protocol_bounds_check" CHECK (("execution_events"."host_sequence" IS NULL OR "execution_events"."host_sequence" >= 0) AND ("execution_events"."run_sequence" IS NULL OR "execution_events"."run_sequence" >= 0) AND ("execution_events"."assignment_epoch" IS NULL OR "execution_events"."assignment_epoch" >= 1) AND ("execution_events"."payload_bytes" IS NULL OR "execution_events"."payload_bytes" BETWEEN 0 AND 1048576) AND ("execution_events"."source" <> 'host' OR ("execution_events"."execution_host_id" IS NOT NULL AND "execution_events"."host_boot_id" IS NOT NULL AND "execution_events"."envelope_version" = 1)));